SELECT model, row_id, action, seq, source, total, batch, upload_id, sent, completed, CASE WHEN error_kind = 'source_failed' THEN 'source_failed:' || error_message ELSE error_message END, created_at, inline, size, sha256, mutation_path, mutation_body, on_failure, steps_path, steps_body, transfer_id, cycle_id, signed_id, aborted, op_id, fields, attempts FROM sync_upload ORDER BY seq
